package com.lifeorganizer;
import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import java.io.*;import java.sql.*;import java.util.zip.*;
/** Account-scoped backup and restore. The signed-in user's records are exported; credentials are never included. */
public class BackupRestoreView extends VBox {
 private final int userId;private final Label status=new Label("Backup contains this account's records, not login credentials.");
 private static final String[] TABLES={"calendar_events","reminder_actions","expense_budgets","expenses","bills","tasks","groceries","medicines","documents","audit_logs"};
 public BackupRestoreView(int id){userId=id;setPadding(new Insets(22));setSpacing(14);Label h=new Label("Backup & Restore");h.setStyle("-fx-font-size:25px;-fx-font-weight:bold;");Button backup=new Button("Create backup ZIP"),restore=new Button("Restore from backup ZIP");backup.setOnAction(e->backup());restore.setOnAction(e->restore());getChildren().addAll(h,new Label("Create a ZIP backup of your records. Restore replaces records for this account with the backup contents."),new HBox(10,backup,restore),status);}
 private void backup(){FileChooser fc=new FileChooser();fc.setInitialFileName("life-organizer-backup.zip");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("ZIP backup","*.zip"));File f=fc.showSaveDialog(getScene().getWindow());if(f==null)return;try(Connection c=Db.connect();ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){z.putNextEntry(new ZipEntry("backup.sql"));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(z,java.nio.charset.StandardCharsets.UTF_8));w.write("-- Life Organizer account backup. user_id="+userId+"\n");for(String table:TABLES){try(PreparedStatement p=c.prepareStatement("SELECT * FROM "+table+" WHERE user_id=?")){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){ResultSetMetaData m=r.getMetaData();int n=m.getColumnCount();while(r.next()){StringBuilder sql=new StringBuilder("INSERT INTO "+table+"(");for(int i=1;i<=n;i++){if(i>1)sql.append(',');sql.append(m.getColumnName(i));}sql.append(") VALUES(");for(int i=1;i<=n;i++){if(i>1)sql.append(',');Object v=r.getObject(i);if(v==null)sql.append("NULL");else if(v instanceof Number)sql.append(v);else sql.append('\'').append(v.toString().replace("\\","\\\\").replace("'","\\'").replace("\r","\\r").replace("\n","\\n")).append('\'');}sql.append(");\n");w.write(sql.toString());}}}}w.flush();z.closeEntry();status.setText("Backup created: "+f.getAbsolutePath());}catch(Exception e){status.setText("Backup failed: "+e.getMessage());}}
 private void restore(){FileChooser fc=new FileChooser();fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("ZIP backup","*.zip"));File f=fc.showOpenDialog(getScene().getWindow());if(f==null)return;Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Restore will DELETE current records for this account and replace them with the backup. Continue?",ButtonType.YES,ButtonType.NO);if(confirm.showAndWait().orElse(ButtonType.NO)!=ButtonType.YES)return;try(Connection c=Db.connect();ZipFile zip=new ZipFile(f)){ZipEntry entry=zip.getEntry("backup.sql");if(entry==null)throw new IOException("backup.sql not found in ZIP");c.setAutoCommit(false);try{String[] order={"reminder_actions","calendar_events","expense_budgets","expenses","bills","tasks","groceries","medicines","documents","audit_logs"};for(String t:order)try(PreparedStatement p=c.prepareStatement("DELETE FROM "+t+" WHERE user_id=?")){p.setInt(1,userId);p.executeUpdate();}try(BufferedReader r=new BufferedReader(new InputStreamReader(zip.getInputStream(entry),java.nio.charset.StandardCharsets.UTF_8));Statement s=c.createStatement()){String line;while((line=r.readLine())!=null){line=line.trim();if(line.startsWith("INSERT INTO ")){if(!line.contains("VALUES")||!line.endsWith(";"))throw new IOException("Invalid backup statement");s.executeUpdate(line.substring(0,line.length()-1));}}}c.commit();status.setText("Restore completed. Refresh the relevant module views.");}catch(Exception ex){c.rollback();throw ex;}finally{c.setAutoCommit(true);}}catch(Exception e){status.setText("Restore failed: "+e.getMessage());}}
}
